create table ai_detections (confidence numeric(5,4) not null, is_anomaly boolean not null, processing_time_ms integer, ai_model_version_id bigint, captured_at timestamp(6) with time zone not null, created_at timestamp(6) with time zone not null, evidence_file_id bigint, id bigint generated by default as identity, offset_ms bigint, processed_at timestamp(6) with time zone, proctoring_event_id bigint, proctoring_session_id bigint not null, updated_at timestamp(6) with time zone, detection_type varchar(16) not null check ((detection_type in ('FACE','OBJECT','BEHAVIOR','AUDIO'))), model_version varchar(32) not null, model_name varchar(100) not null, raw_output jsonb, primary key (id));
create table ai_model_versions (confidence_threshold numeric(5,4) not null, detection_threshold numeric(5,4) not null, activated_at timestamp(6) with time zone, activated_by_user_id bigint, ai_model_id bigint not null, created_at timestamp(6) with time zone not null, deprecated_at timestamp(6) with time zone, id bigint generated by default as identity, updated_at timestamp(6) with time zone, status varchar(16) not null check ((status in ('DRAFT','CANDIDATE','SHADOW','ACTIVE','DEPRECATED','RETIRED'))), version varchar(32) not null, artifact_checksum varchar(64), artifact_ref varchar(512), release_notes varchar(2000), configuration jsonb, primary key (id), constraint uk_ai_model_versions unique (ai_model_id, version));
create table ai_models (is_active boolean not null, runs_on_client boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, purpose varchar(32) not null check ((purpose in ('FACE_DETECTION','FACE_VERIFICATION','HEAD_POSE','GAZE_ESTIMATION','OBJECT_DETECTION','PERSON_DETECTION','SPEECH_DETECTION','VOICE_DIARIZATION','BEHAVIOR_ANALYSIS','RISK_SCORING','EXCEL_ANOMALY_DETECTION'))), code varchar(64) not null, vendor varchar(100), name varchar(150) not null, description varchar(1000), primary key (id), constraint uk_ai_models_code unique (code));
create table answer_revisions (auto_saved boolean not null, response_numeric numeric(18,6), revision_no integer not null, attempt_answer_id bigint not null, client_timestamp timestamp(6) with time zone, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, saved_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone, ip_address varchar(45), response_text varchar(8000), selected_option_ids jsonb, primary key (id), constraint uk_answer_revisions unique (attempt_answer_id, revision_no));
create table answer_timing_anomalies (actual_seconds integer not null, answer_correct boolean not null, expected_seconds integer, ratio numeric(8,4), revision_count integer not null, attempt_answer_id bigint not null, created_at timestamp(6) with time zone not null, exam_attempt_id bigint not null, exam_question_id bigint not null, flagged_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, anomaly_type varchar(24) not null check ((anomaly_type in ('TOO_FAST_CORRECT','TOO_FAST_HIGH_SCORE','ZERO_TIME_CORRECT','BURST_SUBMIT'))), primary key (id));
create table api_clients (rate_limit_per_minute integer, created_at timestamp(6) with time zone not null, created_by_user_id bigint, expires_at timestamp(6) with time zone, id bigint generated by default as identity, last_used_at timestamp(6) with time zone, revoked_at timestamp(6) with time zone, secret_rotated_at timestamp(6) with time zone, updated_at timestamp(6) with time zone, status varchar(16) not null check ((status in ('ACTIVE','SUSPENDED','REVOKED','EXPIRED'))), last_used_ip varchar(45), client_id varchar(64) not null, client_secret_hash varchar(128) not null, name varchar(150) not null, allowed_ip_ranges varchar(500), description varchar(500), allowed_scopes varchar(1000) not null, revoked_reason varchar(255), primary key (id), constraint uk_api_clients_client_id unique (client_id), constraint uk_api_clients_secret unique (client_secret_hash));
create table attempt_answer_options (sequence_no integer, attempt_answer_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, question_option_id bigint not null, updated_at timestamp(6) with time zone, primary key (id), constraint uk_attempt_answer_options unique (attempt_answer_id, question_option_id));
create table attempt_answers (flagged_by_candidate boolean not null, is_correct boolean, points_awarded numeric(9,2), response_numeric numeric(18,6), revision_count integer not null, time_spent_seconds integer not null, answered_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, exam_attempt_id bigint not null, exam_question_id bigint not null, graded_at timestamp(6) with time zone, graded_by_user_id bigint, id bigint generated by default as identity, updated_at timestamp(6) with time zone, grading_status varchar(24) not null check ((grading_status in ('NOT_REQUIRED','PENDING','IN_PROGRESS','GRADED','REGRADED'))), attachment_path varchar(512), grader_comment varchar(2000), response_text varchar(8000), primary key (id), constraint uk_attempt_answers unique (exam_attempt_id, exam_question_id));
create table attempt_pause_requests (created_at timestamp(6) with time zone not null, decided_at timestamp(6) with time zone, decided_by_user_id bigint, exam_attempt_id bigint not null, id bigint generated by default as identity, requested_at timestamp(6) with time zone not null, requested_by_user_id bigint, resumed_at timestamp(6) with time zone, updated_at timestamp(6) with time zone, status varchar(16) not null check ((status in ('PENDING','APPROVED','DENIED','AUTO_APPROVED'))), decision_note varchar(500), reason varchar(500), primary key (id));
create table attempt_resumptions (auto_approved boolean not null, approved_by_user_id bigint, created_at timestamp(6) with time zone not null, exam_attempt_id bigint not null, id bigint generated by default as identity, resumed_at timestamp(6) with time zone not null, risk_event_id bigint, time_away_seconds bigint not null, updated_at timestamp(6) with time zone, reason varchar(24) not null check ((reason in ('BROWSER_CRASH','NETWORK_DROP','DEVICE_REBOOT','POWER_LOSS','PROCTOR_INITIATED'))), new_session_token_hash varchar(128), previous_session_token_hash varchar(128), primary key (id));
create table attempt_timelines (entry_count integer not null, version integer not null, created_at timestamp(6) with time zone not null, exam_attempt_id bigint not null, generated_by_user_id bigint, id bigint generated by default as identity, rendered_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone, checksum_sha256 varchar(64), timeline_json jsonb, primary key (id), constraint uk_attempt_timelines_version unique (exam_attempt_id, version));
create table audio_detections (average_db numeric(6,2), peak_db numeric(6,2), signal_to_noise_ratio numeric(6,2), speaker_count integer, speech_ratio numeric(5,4), unknown_speaker boolean not null, ai_detection_id bigint not null, created_at timestamp(6) with time zone not null, duration_ms bigint, id bigint generated by default as identity, language_code varchar(8), updated_at timestamp(6) with time zone, window_end_at timestamp(6) with time zone not null, window_start_at timestamp(6) with time zone not null, audio_event_type varchar(32) not null check ((audio_event_type in ('SPEECH_DETECTED','MULTIPLE_VOICES','BACKGROUND_NOISE','AUDIO_INTERRUPTION','PROLONGED_SILENCE','SUSPICIOUS_AUDIO'))), transcript_excerpt varchar(1000), primary key (id), constraint uk_audio_detections_detection unique (ai_detection_id));
create table audit_logs (actor_user_id bigint, created_at timestamp(6) with time zone not null, entity_id bigint, id bigint generated by default as identity, occurred_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone, outcome varchar(16) not null check ((outcome in ('SUCCESS','FAILURE','DENIED'))), action varchar(32) not null check ((action in ('CREATE','UPDATE','DELETE','LOGIN','LOGOUT','PUBLISH','ASSIGN','START_ATTEMPT','SUBMIT_ATTEMPT','GRADE','SCORE_OVERRIDE','TERMINATE_ATTEMPT','VIEW_EVIDENCE','EXPORT','CONFIG_CHANGE','PERMISSION_CHANGE','MODEL_CHANGE','PAYMENT_METHOD_ADDED','PAYMENT_METHOD_REMOVED','PAYMENT_METHOD_SET_DEFAULT','PAYMENT_REFUNDED','PAYMENT_DISPUTED'))), ip_address varchar(45), actor_role varchar(48), entity_type varchar(64) not null, request_id varchar(64), user_agent varchar(512), reason varchar(1000), entity_label varchar(255), after_state jsonb, before_state jsonb, primary key (id));
create table behavior_detections (audio_related boolean not null, baseline_deviation numeric(8,4), intensity_score numeric(5,4), occurrence_count integer not null, ai_detection_id bigint not null, created_at timestamp(6) with time zone not null, duration_ms bigint, id bigint generated by default as identity, updated_at timestamp(6) with time zone, window_end_at timestamp(6) with time zone not null, window_start_at timestamp(6) with time zone not null, behavior_type varchar(32) not null check ((behavior_type in ('LOOKING_AWAY','LEAVING_SEAT','FACE_OUT_OF_FRAME','TALKING','BACKGROUND_VOICE','SUSPICIOUS_MOVEMENT','RAPID_TYPING_BURST','PROLONGED_IDLE','SCREEN_OCCLUSION','REPEATED_TAB_SWITCH'))), primary key (id), constraint uk_behavior_detections_detection unique (ai_detection_id));
create table code_execution_results (memory_kb integer, passed boolean not null, runtime_ms integer, attempt_answer_id bigint not null, code_test_case_id bigint not null, created_at timestamp(6) with time zone not null, executed_at timestamp(6) with time zone, id bigint generated by default as identity, updated_at timestamp(6) with time zone, error_message varchar(2000), actual_output varchar(4000), primary key (id), constraint uk_code_execution_results unique (attempt_answer_id, code_test_case_id));
create table code_test_cases (points numeric(9,2), sequence_no integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, question_id bigint not null, updated_at timestamp(6) with time zone, visibility varchar(16) not null check ((visibility in ('SAMPLE','HIDDEN'))), expected_output varchar(4000) not null, input_data varchar(4000), primary key (id), constraint uk_code_test_cases_order unique (question_id, sequence_no));
create table consent_records (consented_at timestamp(6) with time zone not null, created_at timestamp(6) with time zone not null, exam_attempt_id bigint not null, id bigint generated by default as identity, privacy_notice_id bigint not null, updated_at timestamp(6) with time zone, withdrawn_at timestamp(6) with time zone, notice_version varchar(32) not null, ip_address varchar(45), user_agent varchar(512), primary key (id));
