create table device_trust_records (distinct_candidate_count integer not null, sighting_count integer not null, created_at timestamp(6) with time zone not null, exam_id bigint not null, first_seen_at timestamp(6) with time zone not null, flagged_at timestamp(6) with time zone, id bigint generated by default as identity, last_seen_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone, trust_level varchar(24) not null check ((trust_level in ('UNKNOWN','KNOWN','SHARED_SUSPECTED','SHARED_CONFIRMED','BLOCKED'))), device_fingerprint varchar(128) not null, flagged_reason varchar(500), distinct_candidate_ids jsonb, primary key (id), constraint uk_device_trust_records unique (device_fingerprint, exam_id));
