create table exam_results (correct_count integer not null, final_score numeric(9,2) not null, incorrect_count integer not null, max_score numeric(9,2) not null, passed boolean, pending_manual_count integer not null, percentage numeric(5,2), raw_score numeric(9,2) not null, released_to_candidate boolean not null, risk_score numeric(5,2), score_adjustment numeric(9,2), unanswered_count integer not null, candidate_user_id bigint not null, created_at timestamp(6) with time zone not null, exam_attempt_id bigint not null, exam_id bigint not null, grade varchar(8), graded_at timestamp(6) with time zone, graded_by_user_id bigint, id bigint generated by default as identity, published_at timestamp(6) with time zone, review_case_id bigint, time_spent_seconds bigint, updated_at timestamp(6) with time zone, grading_mode varchar(16) not null check ((grading_mode in ('AUTO','MANUAL','HYBRID'))), risk_level varchar(16) check ((risk_level in ('LOW','MEDIUM','HIGH','CRITICAL'))), integrity_status varchar(24) not null check ((integrity_status in ('CLEAN','FLAGGED','UNDER_REVIEW','INVALIDATED'))), status varchar(24) not null check ((status in ('PROVISIONAL','PENDING_REVIEW','WITHHELD','FINAL','VOID'))), certificate_serial varchar(64), primary key (id), constraint uk_exam_results_attempt unique (exam_attempt_id));
