create table exam_window_overrides (created_at timestamp(6) with time zone not null, exam_assignment_id bigint not null, expires_at timestamp(6) with time zone, granted_at timestamp(6) with time zone not null, granted_by_user_id bigint not null, id bigint generated by default as identity, overridden_window_end_at timestamp(6) with time zone not null, overridden_window_start_at timestamp(6) with time zone not null, supersedes_override_id bigint, updated_at timestamp(6) with time zone, reason varchar(1000) not null, justification_ref varchar(255), primary key (id));
create table exams (allowed_tab_switches integer, auto_review_risk_threshold integer, auto_terminate_risk_threshold integer, block_copy_paste boolean not null, detect_audio boolean not null, detect_face boolean not null, detect_gaze boolean not null, detect_multiple_faces boolean not null, detect_objects boolean not null, detect_tab_switch boolean not null, duration_minutes integer, evidence_retention_days integer, excel_autosave_interval_seconds integer, excel_external_app_blocked boolean not null, excel_iterative_calc_max_iterations integer, excel_macros_allowed boolean not null, excel_precision_as_displayed boolean not null, excel_runtime_required boolean not null, excel_snapshot_interval_minutes integer, excel_volatile_functions_pinned boolean not null, force_fullscreen boolean not null, hold_results_for_review boolean not null, max_attempts integer not null, monitor_screen boolean not null, passing_score numeric(9,2), require_environment_scan boolean not null, require_identity_check boolean not null, require_microphone boolean not null, require_screen_share boolean not null, require_webcam boolean not null, retain_audio_transcript boolean not null, show_result_immediately boolean not null, shuffle_sections boolean not null, total_points numeric(9,2), version integer not null, closes_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, created_by_user_id bigint not null, id bigint generated by default as identity, opens_at timestamp(6) with time zone, updated_at timestamp(6) with time zone, excel_copy_paste_policy varchar(16) not null check ((excel_copy_paste_policy in ('ALLOW','BLOCK','LOG'))), excel_cut_drag_fill_policy varchar(16) not null check ((excel_cut_drag_fill_policy in ('ALLOW','BLOCK','LOG'))), excel_recalc_mode varchar(16) not null check ((excel_recalc_mode in ('AUTOMATIC','MANUAL','ITERATIVE'))), public_id uuid not null, grading_mode varchar(32) not null check ((grading_mode in ('AUTO','MANUAL','HYBRID'))), proctoring_mode varchar(32) not null check ((proctoring_mode in ('NONE','AI_ONLY','LIVE_PROCTOR','RECORD_AND_REVIEW','HYBRID'))), status varchar(32) not null check ((status in ('DRAFT','SCHEDULED','PUBLISHED','ACTIVE','CLOSED','ARCHIVED'))), code varchar(64) not null, title varchar(200) not null, description varchar(2000), instructions varchar(4000), primary key (id), constraint uk_exams_code unique (code), constraint uk_exams_public_id unique (public_id));
