create table excel_macro_executions (allowed boolean not null, duration_ms integer, exit_code integer, created_at timestamp(6) with time zone not null, excel_session_id bigint not null, executed_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, macro_name varchar(150) not null, input_summary varchar(1000), output_summary varchar(1000), primary key (id));
create table excel_sessions (created_at timestamp(6) with time zone not null, exam_attempt_id bigint not null, id bigint generated by default as identity, proctoring_session_id bigint, started_at timestamp(6) with time zone, submitted_at timestamp(6) with time zone, updated_at timestamp(6) with time zone, integrity_status varchar(16) check ((integrity_status in ('VALID','TAMPERED','INCONCLUSIVE'))), public_id uuid not null, status varchar(16) not null check ((status in ('PENDING','ACTIVE','SUBMITTED','CRASHED','RECOVERED'))), engine_used varchar(24) check ((engine_used in ('LIBREOFFICE','ONLYOFFICE','SHEETJS_HYPERFORMULA','OFFICE_SCRIPTS'))), final_checksum_sha256 varchar(64), sandbox_container_id varchar(128), primary key (id), constraint uk_excel_sessions_attempt unique (exam_attempt_id), constraint uk_excel_sessions_public_id unique (public_id));
create table excel_sheet_operations (created_at timestamp(6) with time zone not null, excel_session_id bigint not null, id bigint generated by default as identity, occurred_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone, operation_type varchar(16) not null check ((operation_type in ('INSERT','DELETE','RENAME','HIDE','UNHIDE','PROTECT','UNPROTECT'))), sheet_name varchar(100) not null, detail varchar(500), primary key (id));
create table face_detections (box_height float(53), box_width float(53), box_x float(53), box_y float(53), eyes_closed boolean, face_count integer not null, head_pitch numeric(6,2), head_roll numeric(6,2), head_yaw numeric(6,2), identity_match_score numeric(5,4), identity_matched boolean, liveness_score numeric(5,4), mask_or_occlusion_detected boolean not null, spoof_suspected boolean not null, ai_detection_id bigint not null, created_at timestamp(6) with time zone not null, gaze_off_screen_ms bigint, id bigint generated by default as identity, updated_at timestamp(6) with time zone, gaze_direction varchar(16) check ((gaze_direction in ('ON_SCREEN','LEFT','RIGHT','UP','DOWN','AWAY','UNKNOWN'))), primary key (id), constraint uk_face_detections_detection unique (ai_detection_id));
create table group_memberships (is_active boolean not null, added_by_user_id bigint, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, joined_at timestamp(6) with time zone not null, left_at timestamp(6) with time zone, student_group_id bigint not null, updated_at timestamp(6) with time zone, user_id bigint not null, primary key (id), constraint uk_group_memberships unique (student_group_id, user_id));
create table identity_verifications (liveness_score numeric(5,4), match_score numeric(5,4), match_threshold numeric(5,4), sequence_no integer not null, candidate_user_id bigint not null, captured_evidence_id bigint, created_at timestamp(6) with time zone not null, document_last4 varchar(8), exam_attempt_id bigint not null, id bigint generated by default as identity, proctoring_session_id bigint, updated_at timestamp(6) with time zone, verified_at timestamp(6) with time zone, verified_by_user_id bigint, status varchar(24) not null check ((status in ('PENDING','IN_PROGRESS','PASSED','FAILED','MANUAL_OVERRIDE','EXPIRED'))), method varchar(32) not null check ((method in ('FACE_MATCH','ID_DOCUMENT','MANUAL_PROCTOR','KNOWLEDGE_CHALLENGE','SECOND_FACTOR'))), document_type varchar(48), failure_reason varchar(500), override_reason varchar(500), reference_photo_path varchar(512), primary key (id));
create table live_session_status (answered_count integer not null, current_question_no integer, is_fullscreen boolean not null, is_window_focused boolean not null, network_latency_ms integer, open_alert_count integer not null, remaining_seconds integer, risk_score numeric(5,2), created_at timestamp(6) with time zone not null, id bigint generated by default as identity, last_event_at timestamp(6) with time zone, last_heartbeat_at timestamp(6) with time zone, proctoring_session_id bigint not null, updated_at timestamp(6) with time zone, camera_status varchar(16) not null check ((camera_status in ('UNAVAILABLE','ACTIVE','DEGRADED','INTERRUPTED','STOPPED'))), candidate_status varchar(16) not null check ((candidate_status in ('ACTIVE','IDLE','SUSPENDED'))), connection_status varchar(16) not null check ((connection_status in ('CONNECTED','UNSTABLE','RECONNECTING','DISCONNECTED'))), microphone_status varchar(16) not null check ((microphone_status in ('UNAVAILABLE','ACTIVE','DEGRADED','INTERRUPTED','STOPPED'))), risk_level varchar(16) check ((risk_level in ('LOW','MEDIUM','HIGH','CRITICAL'))), screen_status varchar(16) not null check ((screen_status in ('UNAVAILABLE','ACTIVE','DEGRADED','INTERRUPTED','STOPPED'))), updated_by_node varchar(64), websocket_id varchar(128), primary key (id), constraint uk_live_session_status_session unique (proctoring_session_id));
create table login_attempts (geo_country varchar(2), attempted_at timestamp(6) with time zone not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, user_id bigint, outcome varchar(32) not null check ((outcome in ('SUCCESS','BAD_CREDENTIALS','ACCOUNT_LOCKED','ACCOUNT_DISABLED','EMAIL_NOT_VERIFIED','TOKEN_EXPIRED','MFA_REQUIRED','MFA_FAILED'))), ip_address varchar(45), device_fingerprint varchar(128), user_agent varchar(512), email varchar(255) not null, failure_detail varchar(255), primary key (id));
create table model_performance_metrics (metric_value numeric(12,4) not null, ai_model_version_id bigint not null, computed_at timestamp(6) with time zone not null, created_at timestamp(6) with time zone not null, false_negative_count bigint, false_positive_count bigint, id bigint generated by default as identity, sample_count bigint not null, true_positive_count bigint, updated_at timestamp(6) with time zone, window_end_at timestamp(6) with time zone not null, window_start_at timestamp(6) with time zone not null, metric_type varchar(32) not null check ((metric_type in ('PRECISION','RECALL','F1_SCORE','ACCURACY','FALSE_POSITIVE_RATE','FALSE_NEGATIVE_RATE','LATENCY_P95_MS','THROUGHPUT_FPS'))), note varchar(500), primary key (id), constraint uk_model_performance unique (ai_model_version_id, metric_type, window_start_at));
create table notification_suppressions (is_active boolean not null, max_per_window integer, window_end_local time(0), window_seconds integer, window_start_local time(0), created_at timestamp(6) with time zone not null, created_by_user_id bigint, id bigint generated by default as identity, recipient_user_id bigint, updated_at timestamp(6) with time zone, channel varchar(16) check ((channel in ('EMAIL','SMS','IN_APP','PUSH','WEBHOOK'))), suppression_kind varchar(24) not null check ((suppression_kind in ('QUIET_HOURS','OPT_OUT','RATE_LIMIT','DUPLICATE_WINDOW'))), notification_type varchar(32) check ((notification_type in ('ACCOUNT_VERIFICATION','PASSWORD_RESET','EXAM_INVITATION','EXAM_REMINDER','EXAM_STARTED','EXAM_SUBMITTED','ATTEMPT_TERMINATED','REVIEW_ASSIGNED','REVIEW_COMPLETED','RESULT_PUBLISHED','HIGH_RISK_ALERT','SYSTEM_ALERT'))), primary key (id));
