create table object_detections (box_height float(53), box_width float(53), box_x float(53), box_y float(53), is_prohibited boolean not null, object_count integer not null, persisted_frames integer, proximity_score numeric(5,4), ai_detection_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, object_class varchar(32) not null check ((object_class in ('MOBILE_PHONE','BOOK','PAPER_NOTES','SECOND_LAPTOP','SECOND_MONITOR','EARPHONE','SMARTWATCH','CAMERA','ADDITIONAL_PERSON','UNKNOWN_OBJECT'))), object_label varchar(100), primary key (id), constraint uk_object_detections_detection unique (ai_detection_id));
