escription varchar(500), payload jsonb, primary key (id));
create table proctoring_reports (includes_evidence boolean not null, risk_score numeric(5,2), version integer not null, created_at timestamp(6) with time zone not null, exam_attempt_id bigint not null, expires_at timestamp(6) with time zone, generated_at timestamp(6) with time zone, id bigint generated by default as identity, proctoring_session_id bigint, requested_at timestamp(6) with time zone not null, requested_by_user_id bigint, review_case_id bigint, risk_assessment_id bigint, size_bytes bigint, updated_at timestamp(6) with time zone, format varchar(16) not null check ((format in ('PDF','HTML','JSON','ZIP_BUNDLE'))), public_id uuid not null, status varchar(16) not null check ((status in ('QUEUED','GENERATING','AVAILABLE','FAILED','EXPIRED'))), final_integrity_status varchar(24) check ((final_integrity_status in ('CLEAN','FLAGGED','UNDER_REVIEW','INVALIDATED'))), checksum_sha256 varchar(64), failure_reason varchar(500), storage_path varchar(512), summary_snapshot jsonb, primary key (id), constraint uk_proctoring_reports_public_id unique (public_id), constraint uk_proctoring_reports_version unique (exam_attempt_id, version));
