create table question_options (is_correct boolean not null, option_weight numeric(9,2), sequence_no integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, label varchar(8), question_id bigint not null, updated_at timestamp(6) with time zone, feedback varchar(500), media_path varchar(512), content varchar(2000) not null, match_key varchar(255), primary key (id), constraint uk_question_options_order unique (question_id, sequence_no));
create table question_states (display_order integer not null, time_on_question_seconds integer not null, view_count integer not null, created_at timestamp(6) with time zone not null, exam_attempt_id bigint not null, exam_question_id bigint not null, first_viewed_at timestamp(6) with time zone, id bigint generated by default as identity, last_viewed_at timestamp(6) with time zone, locked_at timestamp(6) with time zone, updated_at timestamp(6) with time zone, state varchar(16) not null check ((state in ('UNSEEN','VIEWED','ANSWERED','FLAGGED','SKIPPED','LOCKED'))), option_order varchar(255), primary key (id), constraint uk_question_states unique (exam_attempt_id, exam_question_id));
create table question_tag_link (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, question_id bigint not null, question_tag_id bigint not null, updated_at timestamp(6) with time zone, primary key (id), constraint uk_question_tag_link unique (question_id, question_tag_id));
