create table questions (default_points numeric(9,2) not null, execution_memory_limit_mb integer, execution_time_limit_ms integer, expected_seconds integer, numeric_tolerance numeric(12,6), version integer not null, workbook_has_external_links boolean not null, workbook_has_macros boolean not null, workbook_sheet_count integer, created_at timestamp(6) with time zone not null, created_by_user_id bigint, id bigint generated by default as identity, parent_question_id bigint, question_category_id bigint, updated_at timestamp(6) with time zone, workbook_size_bytes bigint, difficulty varchar(16) not null check ((difficulty in ('EASY','MEDIUM','HARD','EXPERT'))), programming_language varchar(16) check ((programming_language in ('PYTHON','JAVA','JAVASCRIPT','TYPESCRIPT','CPP','C','CSHARP','GO','RUST','SQL'))), status varchar(16) not null check ((status in ('DRAFT','ACTIVE','RETIRED'))), workbook_file_type varchar(16) check ((workbook_file_type in ('XLSX','XLSM','XLSB','CSV','ODS'))), excel_macro_policy varchar(24) check ((excel_macro_policy in ('OFF','SANDBOXED','ALLOWED_WHITELIST'))), question_type varchar(32) not null check ((question_type in ('SINGLE_CHOICE','MULTIPLE_CHOICE','TRUE_FALSE','SHORT_ANSWER','ESSAY','NUMERIC','MATCHING','ORDERING','FILL_IN_BLANK','CODE','SPREADSHEET'))), code varchar(64), workbook_checksum_sha256 varchar(64), topic varchar(120), media_path varchar(512), workbook_storage_path varchar(512), answer_key varchar(2000), explanation varchar(2000), stem varchar(4000) not null, starter_code varchar(8000), primary key (id), constraint uk_questions_code unique (code));
