create table result_withholdings (created_at timestamp(6) with time zone not null, exam_result_id bigint not null, id bigint generated by default as identity, released_at timestamp(6) with time zone, released_by_user_id bigint, review_case_id bigint, risk_assessment_id bigint, updated_at timestamp(6) with time zone, withheld_at timestamp(6) with time zone not null, withheld_by_user_id bigint, reason varchar(24) not null check ((reason in ('RISK_THRESHOLD','OPEN_REVIEW_CASE','PENDING_MANUAL_GRADING','APPEAL_FILED','EXTERNAL_HOLD'))), threshold_version varchar(32), release_reason varchar(1000), primary key (id));
create table retake_grants (additional_attempts integer not null, candidate_user_id bigint not null, consumed_at timestamp(6) with time zone, consumed_by_attempt_id bigint, created_at timestamp(6) with time zone not null, exam_assignment_id bigint not null, expires_at timestamp(6) with time zone, granted_at timestamp(6) with time zone not null, granted_by_user_id bigint not null, id bigint generated by default as identity, review_decision_id bigint not null, supersedes_grant_id bigint, updated_at timestamp(6) with time zone, reason varchar(1000) not null, primary key (id));
create table review_cases (candidate_notified boolean not null, sla_breached boolean not null, assigned_at timestamp(6) with time zone, assigned_reviewer_user_id bigint, closed_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, due_at timestamp(6) with time zone, exam_attempt_id bigint not null, id bigint generated by default as identity, opened_at timestamp(6) with time zone not null, opened_by_user_id bigint, risk_assessment_id bigint, updated_at timestamp(6) with time zone, priority varchar(16) not null check ((priority in ('LOW','NORMAL','HIGH','URGENT'))), status varchar(24) not null check ((status in ('OPEN','ASSIGNED','IN_REVIEW','PENDING_INFO','ESCALATED','RESOLVED','CLOSED'))), case_number varchar(32) not null, final_outcome varchar(32) check ((final_outcome in ('CLEARED','WARNING_ISSUED','SCORE_ADJUSTED','ATTEMPT_INVALIDATED','RETAKE_GRANTED','ESCALATED','NO_ACTION'))), open_reason varchar(500) not null, summary varchar(2000), primary key (id), constraint uk_review_cases_number unique (case_number));
create table review_decisions (is_final boolean not null, score_adjustment numeric(9,2), sequence_no integer not null, created_at timestamp(6) with time zone not null, decided_at timestamp(6) with time zone not null, id bigint generated by default as identity, review_case_id bigint not null, reviewer_user_id bigint not null, supersedes_decision_id bigint, updated_at timestamp(6) with time zone, decision_type varchar(32) not null check ((decision_type in ('CLEAR','WARN_CANDIDATE','ADJUST_SCORE','INVALIDATE_ATTEMPT','GRANT_RETAKE','ESCALATE','REQUEST_MORE_INFO'))), evidence_refs varchar(1000), rationale varchar(2000) not null, primary key (id), constraint uk_review_decisions_order unique (review_case_id, sequence_no));
create table review_findings (weight_disputed boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, item_id bigint not null, review_case_id bigint not null, reviewed_at timestamp(6) with time zone not null, reviewer_user_id bigint not null, updated_at timestamp(6) with time zone, verdict varchar(24) not null check ((verdict in ('VALID','FALSE_POSITIVE','NEEDS_INVESTIGATION','INCONCLUSIVE'))), item_kind varchar(32) not null check ((item_kind in ('PROCTORING_EVENT','AI_DETECTION','SUSPICIOUS_ACTIVITY','EVIDENCE_FILE','RISK_FACTOR'))), comment varchar(1000), primary key (id), constraint uk_review_findings_item unique (review_case_id, item_kind, item_id));
create table review_notes (candidate_visible boolean not null, author_user_id bigint not null, created_at timestamp(6) with time zone not null, edited_at timestamp(6) with time zone, id bigint generated by default as identity, review_case_id bigint not null, updated_at timestamp(6) with time zone, attachment_path varchar(512), body varchar(4000) not null, primary key (id));
create table risk_assessments (auto_action_applied boolean not null, behavior_anomaly_score numeric(5,2), critical_event_count integer not null, environment_score numeric(5,2), face_anomaly_score numeric(5,2), identity_score numeric(5,2), is_latest boolean not null, object_anomaly_score numeric(5,2), risk_score numeric(5,2) not null, total_event_count integer not null, version integer not null, computed_at timestamp(6) with time zone not null, created_at timestamp(6) with time zone not null, exam_attempt_id bigint not null, id bigint generated by default as identity, proctoring_session_id bigint, updated_at timestamp(6) with time zone, risk_level varchar(16) not null check ((risk_level in ('LOW','MEDIUM','HIGH','CRITICAL'))), recommendation varchar(32) not null check ((recommendation in ('ALLOW','MONITOR','FLAG_FOR_REVIEW','INVALIDATE_ATTEMPT','REQUIRE_RETAKE'))), scoring_model_version varchar(32) not null, threshold_version varchar(32), scoring_model varchar(100) not null, recompute_reason varchar(255), primary key (id), constraint uk_risk_assessments_version unique (exam_attempt_id, version));
create table risk_events (contributed_points numeric(6,2) not null, occurrence_count integer not null, weight numeric(6,3) not null, ai_detection_id bigint, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, occurred_at timestamp(6) with time zone, proctoring_event_id bigint, risk_assessment_id bigint not null, updated_at timestamp(6) with time zone, severity varchar(16) not null check ((severity in ('INFO','LOW','MEDIUM','HIGH','CRITICAL'))), factor_code varchar(64) not null, factor_label varchar(150), note varchar(500), primary key (id));
create table risk_factor_configs (base_weight numeric(6,3) not null, confidence_multiplier numeric(6,3) not null, decay_half_life_seconds integer, duration_weight_per_second numeric(6,3), frequency_increment numeric(6,3), grace_occurrences integer not null, is_active boolean not null, is_immediate_critical boolean not null, max_contribution numeric(6,2), min_confidence numeric(5,4), created_at timestamp(6) with time zone not null, effective_from timestamp(6) with time zone not null, effective_to timestamp(6) with time zone, id bigint generated by default as identity, updated_at timestamp(6) with time zone, severity varchar(16) not null check ((severity in ('INFO','LOW','MEDIUM','HIGH','CRITICAL'))), config_version varchar(32) not null, trigger_kind varchar(32) not null check ((trigger_kind in ('PROCTORING_EVENT','AI_DETECTION','SUSPICIOUS_ACTIVITY','DEVICE_SIGNAL','IDENTITY_SIGNAL'))), trigger_code varchar(48) not null, factor_code varchar(64) not null, factor_label varchar(150) not null, primary key (id), constraint uk_risk_factor_configs unique (factor_code, config_version));
create table risk_level_thresholds (alerts_proctor boolean not null, is_active boolean not null, max_score numeric(5,2), min_score numeric(5,2) not null, opens_review_case boolean not null, withholds_result boolean not null, created_at timestamp(6) with time zone not null, effective_from timestamp(6) with time zone not null, effective_to timestamp(6) with time zone, id bigint generated by default as identity, updated_at timestamp(6) with time zone, display_colour varchar(16), risk_level varchar(16) not null check ((risk_level in ('LOW','MEDIUM','HIGH','CRITICAL'))), auto_action varchar(32) not null check ((auto_action in ('NONE','LOG_ONLY','WARN_CANDIDATE','PAUSE_ATTEMPT','LOCK_SCREEN','NOTIFY_PROCTOR','TERMINATE_ATTEMPT'))), config_version varchar(32) not null, recommendation varchar(32) not null check ((recommendation in ('ALLOW','MONITOR','FLAG_FOR_REVIEW','INVALIDATE_ATTEMPT','REQUIRE_RETAKE'))), primary key (id), constraint uk_risk_level_thresholds unique (config_version, risk_level));
create table role_permission (created_at timestamp(6) with time zone not null, granted_at timestamp(6) with time zone not null, granted_by_user_id bigint, id bigint generated by default as identity, permission_id bigint not null, role_id bigint not null, updated_at timestamp(6) with time zone, primary key (id), constraint uk_role_permission unique (role_id, permission_id));
create table roles (is_system boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, code varchar(48) not null, name varchar(100) not null, description varchar(255), primary key (id), constraint uk_roles_code unique (code));
create table security_tokens (created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, id bigint generated by default as identity, invalidated_at timestamp(6) with time zone, issued_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone, used_at timestamp(6) with time zone, user_id bigint not null, purpose varchar(32) not null check ((purpose in ('EMAIL_VERIFICATION','PASSWORD_RESET','ACCOUNT_INVITATION','EMAIL_CHANGE'))), redeemed_ip varchar(45), requested_ip varchar(45), token_hash varchar(128) not null, primary key (id), constraint uk_security_tokens_hash unique (token_hash));
create table shadow_evaluations (active_false_positive_rate numeric(6,4), shadow_false_positive_rate numeric(6,4), active_only_detections bigint not null, active_version_id bigint not null, agreement_count bigint not null, computed_at timestamp(6) with time zone not null, created_at timestamp(6) with time zone not null, disagreement_count bigint not null, id bigint generated by default as identity, shadow_only_detections bigint not null, shadow_version_id bigint not null, updated_at timestamp(6) with time zone, window_end_at timestamp(6) with time zone not null, window_start_at timestamp(6) with time zone not null, recommendation varchar(16) check ((recommendation in ('PROMOTE','HOLD','RETIRE'))), primary key (id));
create table student_groups (is_active boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, owner_user_id bigint, parent_group_id bigint, updated_at timestamp(6) with time zone, group_type varchar(24) not null check ((group_type in ('CLASS','COHORT','DEPARTMENT','PROGRAM','CUSTOM'))), academic_term varchar(64), code varchar(64) not null, name varchar(150) not null, description varchar(500), primary key (id), constraint uk_student_groups_code unique (code));
create table suspicious_activities (confidence numeric(5,4) not null, detection_count integer not null, event_count integer not null, occurrence_count integer not null, adjudicated_at timestamp(6) with time zone, adjudicated_by_user_id bigint, created_at timestamp(6) with time zone not null, duration_ms bigint, exam_attempt_id bigint not null, first_seen_at timestamp(6) with time zone not null, id bigint generated by default as identity, last_seen_at timestamp(6) with time zone not null, primary_detection_id bigint, proctoring_session_id bigint not null, updated_at timestamp(6) with time zone, severity varchar(16) not null check ((severity in ('INFO','LOW','MEDIUM','HIGH','CRITICAL'))), verdict varchar(24) not null check ((verdict in ('DETECTED','CONFIRMED','FALSE_POSITIVE','UNDER_REVIEW','DISMISSED'))), activity_type varchar(32) not null check ((activity_type in ('REPEATED_LOOKING_AWAY','MULTIPLE_FACES','PHONE_DETECTED','NO_FACE','SUSPICIOUS_OBJECT','TAB_SWITCHING','FULLSCREEN_EXIT','AUDIO_EVENT','IMPERSONATION_SUSPECTED','COMBINED_BEHAVIOR'))), rule_code varchar(64), description varchar(500), adjudication_note varchar(1000), contributing_signals jsonb, primary key (id));
create table system_check_items (is_required boolean not null, retry_count integer not null, checked_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, system_check_id bigint not null, updated_at timestamp(6) with time zone, result varchar(16) not null check ((result in ('NOT_RUN','PASSED','WARNING','FAILED','SKIPPED'))), check_type varchar(32) not null check ((check_type in ('BROWSER_COMPATIBILITY','CAMERA','MICROPHONE','SPEAKER','NETWORK_BANDWIDTH','SCREEN_SHARE_PERMISSION','FULLSCREEN','ENVIRONMENT_SCAN','OS_COMPATIBILITY','SECOND_SCREEN','EXCEL_RUNTIME','FORMULA_ENGINE','WORKBOOK_LOAD'))), message varchar(500), measurement jsonb, primary key (id), constraint uk_system_check_items unique (system_check_id, check_type));
create table system_checks (attempt_no integer not null, download_mbps numeric(8,2), failed_check_count integer not null, latency_ms integer, overridden boolean not null, upload_mbps numeric(8,2), candidate_user_id bigint not null, completed_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, exam_attempt_id bigint, exam_id bigint not null, id bigint generated by default as identity, overridden_by_user_id bigint, started_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone, valid_until timestamp(6) with time zone, status varchar(24) not null check ((status in ('IN_PROGRESS','PASSED','PASSED_WITH_WARNINGS','FAILED','EXPIRED'))), ip_address varchar(45), device_fingerprint varchar(128), override_reason varchar(500), user_agent varchar(512), primary key (id));
create table system_settings (is_editable boolean not null, is_secret boolean not null, requires_restart boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, last_changed_at timestamp(6) with time zone, updated_at timestamp(6) with time zone, updated_by_user_id bigint, value_type varchar(16) not null check ((value_type in ('STRING','INTEGER','DECIMAL','BOOLEAN','JSON','DURATION','ENUM'))), category varchar(24) not null check ((category in ('GENERAL','PROCTORING','RISK','EXAM','STORAGE','NOTIFICATION','AI','SECURITY','EXCEL'))), setting_key varchar(128) not null, description varchar(500), default_value varchar(4000), setting_value varchar(4000), validation_rule varchar(255), primary key (id), constraint uk_system_settings_key unique (setting_key));
create table user_role (created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone, granted_at timestamp(6) with time zone not null, granted_by_user_id bigint, id bigint generated by default as identity, role_id bigint not null, updated_at timestamp(6) with time zone, user_id bigint not null, primary key (id), constraint uk_user_role unique (user_id, role_id));
create table user_sessions (created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, id bigint generated by default as identity, issued_at timestamp(6) with time zone not null, last_seen_at timestamp(6) with time zone, revoked_at timestamp(6) with time zone, updated_at timestamp(6) with time zone, user_id bigint not null, ip_address varchar(45), device_fingerprint varchar(128), refresh_token_hash varchar(128) not null, revoked_reason varchar(128), user_agent varchar(512), primary key (id), constraint uk_user_sessions_token unique (refresh_token_hash));
create table users (failed_login_count integer not null, mfa_enabled boolean not null, created_at timestamp(6) with time zone not null, email_verified_at timestamp(6) with time zone, id bigint generated by default as identity, last_login_at timestamp(6) with time zone, locale varchar(8), locked_until timestamp(6) with time zone, mfa_enrolled_at timestamp(6) with time zone, updated_at timestamp(6) with time zone, mfa_method varchar(16) check ((mfa_method in ('TOTP','SMS','EMAIL'))), public_id uuid not null, phone_number varchar(32), status varchar(32) not null check ((status in ('PENDING_VERIFICATION','ACTIVE','SUSPENDED','DISABLED'))), external_ref varchar(64), time_zone varchar(64), full_name varchar(150) not null, enrolment_photo_path varchar(512), voiceprint_path varchar(512), email varchar(255) not null, mfa_secret_encrypted varchar(255), password_hash varchar(255) not null, primary key (id), constraint uk_users_email unique (email), constraint uk_users_public_id unique (public_id), constraint uk_users_external_ref unique (external_ref));
